            if a[i] == b[j]:
                L[i][j] = L[i+1][j+1] + 1
            else:
                L[i][j] = max(L[i+1][j], L[i][j+1])
    # backtrack from start
    i = j = 0
    ma = [True]*n; mb = [True]*m
    while i < n and j < m:
        if a[i] == b[j]:
            ma[i] = False; mb[j] = False; i += 1; j += 1
        elif tie == 'a':
            if L[i+1][j] >= L[i][j+1]: i += 1
            else: j += 1
        else:
            if L[i][j+1] >= L[i+1][j]: j += 1
            else: i += 1
    return ma, mb

def myers_forward(a, b):
    """Classic Myers greedy O(ND) with trace, as in the paper / common implementations."""
    n, m = len(a), len(b)
