            if k == -d or (k != d and V[k-1] < V[k+1]):
                x = V[k+1]
            else:
                x = V[k-1] + 1
            y = x - k
            while x < n and y < m and a[x] == b[y]:
                x += 1; y += 1
            V[k] = x
            if x >= n and y >= m:
                found = True
                break
        if found: break
    # backtrack
    ma = [True]*n; mb = [True]*m
    x, y = n, m
    for d in range(len(trace)-1, -1, -1):
        V = trace[d]
        k = x - y
        if k == -d or (k != d and V.get(k-1, -10**9) < V.get(k+1, -10**9)):
            prev_k = k + 1
        else:
            prev_k = k - 1
        prev_x = V[prev_k]
        prev_y = prev_x - prev_k
