def myers_linear(a, b):
    """Linear space Myers (middle snake divide and conquer), as in the 1986 paper."""
    n, m = len(a), len(b)
    ma = [True]*n; mb = [True]*m
    def middle_snake(a0, a1, b0, b1):
        N = a1 - a0; M = b1 - b0
        maxd = (N + M + 1)//2 + 1
        delta = N - M
        odd = delta % 2 != 0
        Vf = {1: 0}
        Vb = {1: 0}
        for d in range(0, maxd+1):
            for k in range(-d, d+1, 2):
                if k == -d or (k != d and Vf[k-1] < Vf[k+1]):
                    x = Vf[k+1]
                else:
                    x = Vf[k-1] + 1
                y = x - k
                x0, y0 = x, y
                while x < N and y < M and a[a0+x] == b[b0+y]:
                    x += 1; y += 1
                Vf[k] = x
                if odd and (k - delta) >= -(d-1) and (k - delta) <= (d-1):
                    # check overlap with reverse path on diagonal k - delta
                    if x + Vb[k - delta] >= N:
                        return (x0, y0, x, y)
            for k in range(-d, d+1, 2):
                if k == -d or (k != d and Vb[k-1] < Vb[k+1]):
                    x = Vb[k+1]
                else:
                    x = Vb[k-1] + 1
                y = x - k
                x0, y0 = x, y
                while x < N and y < M and a[a1-1-x] == b[b1-1-y]:
                    x += 1; y += 1
