import pickle, glob, sys
def load():
    samples=[]
    for f in sorted(glob.glob('samples_*.pkl')):
        samples += pickle.load(open(f,'rb'))
    return samples
def evaluate(f, samples, verbose=0):
    ok=0; fails=[]
    for rt, at, rm, am in samples:
        ma, mb = f(rt, at)
        if list(ma)==rm and list(mb)==am: ok+=1
        else: fails.append((rt,at,rm,am,ma,mb))
