def make_linear(kmap='correct', fwd_check_parity=True, rev_check_parity=True, prefix_strip=True):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def middle_snake(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            maxd = (N + M + 1)//2 + 1
            delta = N - M
            odd = delta % 2 != 0
            Vf = {1: 0}
            Vb = {1: 0}
            for d in range(0, maxd+1):
                for k in range(-d, d+1, 2):
                    if k == -d or (k != d and Vf[k-1] < Vf[k+1]):
                        x = Vf[k+1]
                    else:
                        x = Vf[k-1] + 1
                    y = x - k
                    x0, y0 = x, y
                    while x < N and y < M and a[a0+x] == b[b0+y]:
                        x += 1; y += 1
                    Vf[k] = x
                    kr = (delta - k) if kmap=='correct' else (k - delta) if kmap=='minus' else k
                    if (odd or not fwd_check_parity) and kr in Vb and kr >= -(d-1) and kr <= (d-1):
                        if x + Vb[kr] >= N:
                            return (x0, y0, x, y)
                for k in range(-d, d+1, 2):
                    if k == -d or (k != d and Vb[k-1] < Vb[k+1]):
                        x = Vb[k+1]
                    else:
                        x = Vb[k-1] + 1
                    y = x - k
                    x0, y0 = x, y
                    while x < N and y < M and a[a1-1-x] == b[b1-1-y]:
                        x += 1; y += 1
                    Vb[k] = x
                    kf = (delta - k) if kmap=='correct' else (k + delta) if kmap=='minus' else k
                    if (not odd or not rev_check_parity) and kf in Vf and kf >= -d and kf <= d:
                        if x + Vf[kf] >= N:
                            return (N - x, M - y, N - x0, M - y0)
            return None
        def rec(a0, a1, b0, b1, depth=0):
            if prefix_strip:
                while a0 < a1 and b0 < b1 and a[a0] == b[b0]:
                    ma[a0] = False; mb[b0] = False; a0 += 1; b0 += 1
                while a0 < a1 and b0 < b1 and a[a1-1] == b[b1-1]:
                    ma[a1-1] = False; mb[b1-1] = False; a1 -= 1; b1 -= 1
            if a0 >= a1 or b0 >= b1:
                return
            if depth > 100: return
            s = middle_snake(a0, a1, b0, b1)
            if s is None: return
            x0, y0, x1, y1 = s
            for i in range(x1 - x0):
                ma[a0+x0+i] = False; mb[b0+y0+i] = False
            if (x0, y0) == (0, 0) and (x1, y1) == (0, 0):
                return
            if (x0,y0)==(0,0) and (x1,y1)==(N:=a1-a0, b1-b0):
                return
            rec(a0, a0+x0, b0, b0+y0, depth+1)
            rec(a0+x1, a1, b0+y1, b1, depth+1)
        rec(0, n, 0, m)
        return ma, mb
    return algo

VARIANTS = {}
for kmap in ('correct','minus','same'):
    for fp in (True, False):
        for rp in (True, False):
            for ps in (True, False):
                VARIANTS[f'lin_{kmap}_f{int(fp)}_r{int(rp)}_p{int(ps)}'] = make_linear(kmap, fp, rp, ps)
