import math
def coglan(a, b):
    n, m = len(a), len(b)
    ma=[True]*n; mb=[True]*m
    def midpoint(left, top, right, bottom):
        size = (right-left) + (bottom-top)
        if size == 0: return None
        mx = (size + 1)//2
        delta = (right-left) - (bottom-top)
        vf = {1: left}
        vb = {1: bottom}
        for d in range(0, mx+1):
            # forwards
            for k in range(d, -d-1, -2):
                c = k - delta
                if k == -d or (k != d and vf[k-1] < vf[k+1]):
                    px = x = vf[k+1]
                else:
                    px = vf[k-1]; x = px + 1
                y = top + (x - left) - k
                py = y if (d == 0 or x != px) else y - 1
                while x < right and y < bottom and a[x] == b[y]:
                    x += 1; y += 1
                vf[k] = x
                if delta % 2 != 0 and -(d-1) <= c <= d-1 and y >= vb[c]:
                    return ((px,py),(x,y))
            # backwards
            for c in range(d, -d-1, -2):
                k = c + delta
                if c == -d or (c != d and vb[c-1] > vb[c+1]):
                    py = y = vb[c+1]
                else:
                    py = vb[c-1]; y = py - 1
                x = left + (y - top) + k
                px = x if (d == 0 or y != py) else x + 1
                while x > left and y > top and a[x-1] == b[y-1]:
                    x -= 1; y -= 1
                vb[c] = y
                if delta % 2 == 0 and -d <= k <= d and x <= vf[k]:
                    return ((x,y),(px,py))
        return None
    def find_path(left, top, right, bottom):
        snake = midpoint(left, top, right, bottom)
        if snake is None: return None
        start, finish = snake
        head = find_path(left, top, start[0], start[1])
        tail = find_path(finish[0], finish[1], right, bottom)
        return (head if head else [start]) + (tail if tail else [finish])
    path = find_path(0, 0, n, m)
    if path is None: return ma, mb
    # walk
    for (x1,y1),(x2,y2) in zip(path, path[1:]):
        # move diagonally? Coglan's walk_diagonal: while x1<x2 and y1<y2 and a[x1]==b[y1]
        while x1 < x2 and y1 < y2 and a[x1] == b[y1]:
            ma[x1]=False; mb[y1]=False; x1+=1; y1+=1
        if x2 - x1 < y2 - y1:
            y1 += 1  # insert
        elif x2 - x1 > y2 - y1:
            x1 += 1  # delete
        while x1 < x2 and y1 < y2 and a[x1] == b[y1]:
            ma[x1]=False; mb[y1]=False; x1+=1; y1+=1
    return ma, mb
