def make(korder='rev', snake='region', skip_empty=True, mark_check=False):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def middle_snake(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            maxd = (N + M + 1)//2 + 1
            delta = N - M
            odd = delta % 2 != 0
            Vf = {1: 0}
            Vb = {1: 0}
            for d in range(0, maxd+1):
                ks = list(range(-d, d+1, 2))
                if korder == 'rev': ks = ks[::-1]
                for k in ks:
                    if k == -d or (k != d and Vf[k-1] < Vf[k+1]):
                        x = Vf[k+1]
                    else:
                        x = Vf[k-1] + 1
                    y = x - k
                    x0, y0 = x, y
                    while x < N and y < M and a[a0+x] == b[b0+y]:
                        x += 1; y += 1
                    Vf[k] = x
                    kr = delta - k
                    if odd and kr >= -(d-1) and kr <= (d-1):
                        xr = Vb[kr]
                        if x + xr >= N:
                            if snake == 'region':
                                sx = N - xr; sy = M - (xr - kr)
                                return (sx, sy, x, y)
                            else:
                                return (x0, y0, x, y)
                for k in ks:
                    if k == -d or (k != d and Vb[k-1] < Vb[k+1]):
                        x = Vb[k+1]
                    else:
                        x = Vb[k-1] + 1
                    y = x - k
                    x0, y0 = x, y
                    while x < N and y < M and a[a1-1-x] == b[b1-1-y]:
                        x += 1; y += 1
                    Vb[k] = x
                    kf = delta - k
                    if not odd and kf >= -d and kf <= d:
                        xf = Vf[kf]
                        if x + xf >= N:
                            if snake == 'region':
                                return (N - x, M - y, xf, xf - kf)
                            else:
                                return (N - x, M - y, N - x0, M - y0)
            return None
        def rec(a0, a1, b0, b1, depth=0):
            if a0 >= a1 or b0 >= b1:
                return
            if depth > 200: raise RuntimeError('depth')
            s = middle_snake(a0, a1, b0, b1)
            if s is None: return
            x0, y0, x1, y1 = s
            for i in range(x1 - x0):
                if mark_check and a[a0+x0+i] != b[b0+y0+i]: continue
                ma[a0+x0+i] = False; mb[b0+y0+i] = False
            if x1 == x0 and skip_empty:
                x1 += 1; y1 += 1
            rec(a0, a0+x0, b0, b0+y0, depth+1)
            rec(a0+x1, a1, b0+y1, b1, depth+1)
        rec(0, n, 0, m)
        return ma, mb
    return algo
