                if sfx == min(N, M):
                    for i in range(sfx): ma[a1-1-i] = False; mb[b1-1-i] = False
                else:
                    p = 0
                    while p < N and p < M and a[a0+p] == b[b0+p]: p += 1
                    for i in range(p): ma[a0+i] = False; mb[b0+i] = False
                    if N > M:
                        for i in range(p, M):
