                            ma[a0+i+1] = False; mb[b0+i] = False
                    else:
                        for i in range(p, N):
                            if a[a0+i] != b[b0+i+1]: raise RuntimeError('d1bad')
                            ma[a0+i] = False; mb[b0+i+1] = False
                return
            # choose snake
            flen = (fs[2][0]-fs[1][0]) if fs else -1
            rlen = (rs[2][0]-rs[1][0]) if rs else -1
            if choose == 'own': use_rev = (who == 'r')
