import itertools
def make(order='pass_fr', korder='asc', kmap='same', timing='both', uncomputed='zero', choose='own', select='first', edit_rec=False, d1=None, cmp='ge'):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def middle(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            delta = N - M
            Vf = {1: 0}; Vb = {1: 0}
            fsn = {}; rsn = {}
            maxd = N + M + 2
            def fstep(d, k):
                if k == -d or (k != d and Vf[k-1] < Vf[k+1]):
                    x = Vf[k+1]; before = (x, x-k-1)
                else:
                    x = Vf[k-1] + 1; before = (x-1, x-k)
                if d == 0: before = (0,0)
                y = x - k
                x0, y0 = x, y
                while x < N and y < M and a[a0+x] == b[b0+y]:
                    x += 1; y += 1
                Vf[k] = x
                s = (before, (x0,y0), (x,y))
                fsn[k] = s
                return s
            def rstep(d, k):
                if k == -d or (k != d and Vb[k-1] < Vb[k+1]):
                    x = Vb[k+1]; before = (x, x-k-1)
                else:
                    x = Vb[k-1] + 1; before = (x-1, x-k)
                if d == 0: before = (0,0)
                y = x - k
                x0, y0 = x, y
                while x < N and y < M and a[a1-1-x] == b[b1-1-y]:
                    x += 1; y += 1
                Vb[k] = x
                # convert to forward coords: after-edit point, snake start, snake end
                s = ((N-before[0], M-before[1]), (N-x, M-y), (N-x0, M-y0))
                rsn[k] = s
                return s
            def okmap(k):
                return k if kmap == 'same' else delta - k
            def getv(V, k):
                if k in V: return V[k]
                return 0 if uncomputed == 'zero' else None
            def fcheck(d, k):
                kr = okmap(k)
                xr = getv(Vb, kr)
                if xr is None: return None
                xf = Vf[k]
                ok = (xf + xr >= N) if cmp == 'ge' else (xf + xr > N)
                if not ok: return None
                return ('f', d, k, fsn[k], rsn.get(kr))
            def rcheck(d, k):
                kf = okmap(k)
                xf = getv(Vf, kf)
                if xf is None: return None
                xr = Vb[k]
                ok = (xf + xr >= N) if cmp == 'ge' else (xf + xr > N)
                if not ok: return None
                return ('r', d, k, fsn.get(kf), rsn[k])
            def pick(cands):
                if not cands: return None
                if select == 'first': return cands[0]
                def slen(c):
                    who, d, k, fs, rs = c
                    s = fs if who == 'f' else rs
                    return s[2][0] - s[1][0]
                if select == 'longest_maxk':
                    cands.sort(key=lambda c: (slen(c), c[2]))
                elif select == 'longest_mink':
                    cands.sort(key=lambda c: (slen(c), -c[2]))
                return cands[-1]
            for d in range(0, maxd+1):
                ks = list(range(-d, d+1, 2))
                if korder == 'desc': ks = ks[::-1]
                if order in ('interleave_fr', 'interleave_rf'):
                    cands = []
                    for k in ks:
                        if order == 'interleave_fr':
                            fstep(d, k)
                            if timing in ('both','fwd'):
                                r = fcheck(d, k)
                                if r:
                                    if select == 'first': return r
                                    cands.append(r)
                            rstep(d, k)
                            if timing in ('both','rev'):
                                r = rcheck(d, k)
                                if r:
                                    if select == 'first': return r
                                    cands.append(r)
                        else:
                            rstep(d, k)
                            if timing in ('both','rev'):
                                r = rcheck(d, k)
                                if r:
                                    if select == 'first': return r
                                    cands.append(r)
                            fstep(d, k)
                            if timing in ('both','fwd'):
                                r = fcheck(d, k)
                                if r:
                                    if select == 'first': return r
                                    cands.append(r)
                    r = pick(cands)
                    if r: return r
                else:
                    first, second = ('f','r') if order == 'pass_fr' else ('r','f')
                    for who in (first, second):
                        cands = []
                        for k in ks:
                            if who == 'f':
                                fstep(d, k)
                                if timing in ('both','fwd'):
                                    r = fcheck(d, k)
                                    if r:
                                        if select == 'first': return r
                                        cands.append(r)
                            else:
                                rstep(d, k)
                                if timing in ('both','rev'):
                                    r = rcheck(d, k)
                                    if r:
                                        if select == 'first': return r
                                        cands.append(r)
                        r = pick(cands)
                        if r: return r
            return None
        def rec(a0, a1, b0, b1, depth=0):
            if a0 >= a1 or b0 >= b1:
                return
            if depth > 100: raise RuntimeError('depth')
            N = a1 - a0; M = b1 - b0
            r = middle(a0, a1, b0, b1)
            if r is None: raise RuntimeError('none')
            who, d, k, fs, rs = r
            D = 2*d - 1 if who == 'f' else 2*d
            if d1 and D <= 1:
                sfx = 0
                while sfx < N and sfx < M and a[a1-1-sfx] == b[b1-1-sfx]: sfx += 1
                if sfx == min(N, M):
                    for i in range(sfx): ma[a1-1-i] = False; mb[b1-1-i] = False
                else:
