                            ma[a0+i+1] = False; mb[b0+i] = False
                    else:
                        for i in range(p, N):
                            if a[a0+i] != b[b0+i+1]: raise RuntimeError('d1bad')
                            ma[a0+i] = False; mb[b0+i+1] = False
                return
            # choose snake
            flen = (fs[2][0]-fs[1][0]) if fs else -1
            rlen = (rs[2][0]-rs[1][0]) if rs else -1
            if choose == 'own': use_rev = (who == 'r')
            elif choose == 'other': use_rev = (who == 'f')
            elif choose == 'longer_own': use_rev = (rlen > flen) if who == 'f' else (rlen >= flen)
            elif choose == 'longer_rev': use_rev = rlen >= flen
            elif choose == 'longer_fwd': use_rev = rlen > flen
            if use_rev and rs is None: use_rev = False
            if not use_rev and fs is None: use_rev = True
            s = rs if use_rev else fs
            edge, (x0,y0), (x1,y1) = s
            for i in range(x1 - x0):
