                rx, ry = x1, y1
            if lx < 0 or ly < 0 or rx > N or ry > M: raise RuntimeError('oob')
            if (lx, ly) == (N, M) or (rx, ry) == (0, 0):
                raise RuntimeError('loop')
            rec(a0, a0+lx, b0, b0+ly, depth+1)
            rec(a0+rx, a1, b0+ry, b1, depth+1)
        rec(0, n, 0, m)
        return ma, mb
    return algo

PARAMS = dict(
    order=['interleave_fr','interleave_rf','pass_fr','pass_rf'],
    korder=['asc','desc'],
    kmap=['same','delta'],
    timing=['both','fwd','rev'],
    uncomputed=['zero','skip'],
    choose=['own','other','longer_own','longer_rev','longer_fwd'],
    select=['first','longest_maxk','longest_mink'],
