def make(korder='asc', choose='xr_ge', fwd_edit_rec=True, rev_edit_rec=True, cmp='ge', order='fr'):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def middle(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            Vf = {1: 0}; Vb = {1: 0}
            maxd = N + M + 2
            for d in range(0, maxd+1):
                ks = list(range(-d, d+1, 2))
                if korder == 'desc': ks = ks[::-1]
                for k in ks:
                    # forward
                    if k == -d or (k != d and Vf[k-1] < Vf[k+1]):
                        x = Vf[k+1]; fb = (x, x-k-1)
                    else:
                        x = Vf[k-1] + 1; fb = (x-1, x-k)
                    if d == 0: fb = (0, 0)
                    y = x - k
                    fx0, fy0 = x, y
                    while x < N and y < M and a[a0+x] == b[b0+y]:
                        x += 1; y += 1
                    Vf[k] = x
                    fx1, fy1 = x, y
                    # reverse
                    if k == -d or (k != d and Vb[k-1] < Vb[k+1]):
                        x = Vb[k+1]; rb = (x, x-k-1)
                    else:
                        x = Vb[k-1] + 1; rb = (x-1, x-k)
                    if d == 0: rb = (0, 0)
                    y = x - k
                    rx0, ry0 = x, y
                    while x < N and y < M and a[a1-1-x] == b[b1-1-y]:
                        x += 1; y += 1
                    Vb[k] = x
                    rx1, ry1 = x, y
                    xf, xr = fx1, rx1
                    ok = (xf + xr >= N) if cmp == 'ge' else (xf + xr > N)
                    if ok:
                        if choose == 'xr_ge': use_rev = xr >= xf
                        elif choose == 'xr_gt': use_rev = xr > xf
                        elif choose == 'longer_rev': use_rev = (rx1-rx0) >= (fx1-fx0)
                        elif choose == 'longer_fwd': use_rev = (rx1-rx0) > (fx1-fx0)
                        if use_rev:
                            s0 = (N - rx1, M - ry1); s1 = (N - rx0, M - ry0)
                            after = (N - rb[0], M - rb[1]) if rev_edit_rec else s1
                            return (s0, s1, s0, after)
                        else:
                            s0 = (fx0, fy0); s1 = (fx1, fy1)
                            before = fb if fwd_edit_rec else s0
                            return (s0, s1, before, s1)
            return None
        def rec(a0, a1, b0, b1, depth=0):
            if a0 >= a1 or b0 >= b1:
                return
            if depth > 100: raise RuntimeError('depth')
            N = a1 - a0; M = b1 - b0
            r = middle(a0, a1, b0, b1)
            if r is None: raise RuntimeError('none')
            (x0, y0), (x1, y1), (lx, ly), (rx, ry) = r
            for i in range(x1 - x0):
