def make(order='ifr', korder='asc', split='F', cover_order='prefix', d1=True, select='first'):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def middle(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            delta = N - M
            Vf = {}; Vb = {}
            maxd = N + M + 2
            def fstep(d, k):
                if k == -d or (k != d and Vf[k-1] < Vf[k+1]): x = Vf[k+1]
                else: x = Vf[k-1] + 1
                y = x - k; x0, y0 = x, y
                while x < N and y < M and a[a0+x] == b[b0+y]: x += 1; y += 1
                Vf[k] = x
                kr = delta - k
                if kr in Vb and x + Vb[kr] >= N:
                    xr = Vb[kr]
                    return (x-x0, k, ('f', d, (x0, y0), (x, y), (N - xr, M - (xr - kr))))
                return None
            def rstep(d, k):
                if k == -d or (k != d and Vb[k-1] < Vb[k+1]): x = Vb[k+1]
                else: x = Vb[k-1] + 1
                y = x - k; x0, y0 = x, y
                while x < N and y < M and a[a1-1-x] == b[b1-1-y]: x += 1; y += 1
                Vb[k] = x
                kf = delta - k
                if kf in Vf and x + Vf[kf] >= N:
                    xf = Vf[kf]
                    return (x-x0, k, ('r', d, (N - x, M - y), (N - x0, M - y0), (xf, xf - kf)))
                return None
            def sel(found):
                if select == 'first': return found[0][2]
                if select == 'longest_maxk': found.sort(key=lambda t:(t[0], t[1]))
                else: found.sort(key=lambda t:(t[0], -t[1]))
                return found[-1][2]
            for d in range(0, maxd+1):
                Vf[d+1] = 0; Vb[d+1] = 0
                if d == 0: Vf[1] = 0; Vb[1] = 0
                ks = list(range(-d, d+1, 2))
                if korder == 'desc': ks = ks[::-1]
                found = []
                for k in ks:
                    if order == 'ifr':
                        r = fstep(d, k)
                        if r: found.append(r)
                        r = rstep(d, k)
                        if r: found.append(r)
                    else:
                        r = rstep(d, k)
                        if r: found.append(r)
                        r = fstep(d, k)
                        if r: found.append(r)
                    if found and select == 'first': return found[0][2]
                if found: return sel(found)
            return None
