def make(forder='asc', rorder='asc', cmp='eq', tie='prefix', select='first', fallback='none'):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def middle(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            delta = N - M
            odd = delta % 2 != 0
            Vf = {1: 0}; Vb = {1: 0}
            maxd = (N + M + 1)//2 + 1
            def ok(s):
                return s == N if cmp == 'eq' else s >= N
            for d in range(0, maxd+1):
                ks = list(range(-d, d+1, 2))
                fks = ks[::-1] if forder == 'desc' else ks
                rks = ks[::-1] if rorder == 'desc' else ks
                for k in fks:
                    if k == -d or (k != d and Vf[k-1] < Vf[k+1]): x = Vf[k+1]
                    else: x = Vf[k-1] + 1
                    y = x - k; x0, y0 = x, y
                    while x < N and y < M and a[a0+x] == b[b0+y]: x += 1; y += 1
                    Vf[k] = x
                    kr = delta - k
                    if odd and -(d-1) <= kr <= (d-1) and ok(x + Vb[kr]):
                        xr = Vb[kr]
                        return ('f', d, (x0, y0), (x, y), (N - xr, M - (xr - kr)))
                for k in rks:
                    if k == -d or (k != d and Vb[k-1] < Vb[k+1]): x = Vb[k+1]
                    else: x = Vb[k-1] + 1
                    y = x - k; x0, y0 = x, y
                    while x < N and y < M and a[a1-1-x] == b[b1-1-y]: x += 1; y += 1
                    Vb[k] = x
                    kf = delta - k
                    if (not odd) and -d <= kf <= d and ok(x + Vf[kf]):
                        xf = Vf[kf]
                        return ('r', d, (N - x, M - y), (N - x0, M - y0), (xf, xf - kf))
            return None
        def pre(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            p = 0
            while p < N and p < M and a[a0+p] == b[b0+p]: p += 1
            s = 0
            while s < N and s < M and a[a1-1-s] == b[b1-1-s]: s += 1
            mn = min(N, M)
            if p + s < mn: return False
            if s > p or (s == p and tie == 'suffix'):
                for i in range(s): ma[a1-1-i] = False; mb[b1-1-i] = False
                for i in range(mn - s): ma[a0+i] = False; mb[b0+i] = False
            else:
                for i in range(p): ma[a0+i] = False; mb[b0+i] = False
                for i in range(mn - p): ma[a1-1-i] = False; mb[b1-1-i] = False
            return True
        def rec(a0, a1, b0, b1, depth=0):
            if a0 >= a1 or b0 >= b1: return
            if depth > 100: raise RuntimeError('depth')
            N = a1 - a0; M = b1 - b0
