//! Minimal ANSI color handling (modeled after common terminal color crates).

use std::fmt;
use std::io::{self, Write};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Black,
    Blue,
    Green,
    Red,
    Cyan,
    Magenta,
    Yellow,
    White,
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Debug)]
pub enum ParseColorErrorKind {
    InvalidName,
    InvalidAnsi256,
    InvalidRgb,
}

#[derive(Debug)]
pub struct ParseColorError {
    kind: ParseColorErrorKind,
    given: String,
}

impl fmt::Display for ParseColorError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self.kind {
            ParseColorErrorKind::InvalidName => write!(
                f,
                "unrecognized color name '{}'. Choose from: \
                 black, blue, green, red, cyan, magenta, yellow, white",
                self.given
            ),
            ParseColorErrorKind::InvalidAnsi256 => write!(
                f,
                "unrecognized ansi256 color number, \
                 should be '[0-255]' (or a hex number), but is '{}'",
                self.given
            ),
            ParseColorErrorKind::InvalidRgb => write!(
                f,
                "unrecognized RGB color triple, \
                 should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'",
                self.given
            ),
        }
    }
}

fn parse_u8_maybe_hex(s: &str) -> Option<u8> {
    if let Ok(n) = s.parse::<u8>() {
        return Some(n);
    }
    if let Some(h) = s.strip_prefix("0x") {
        if let Ok(n) = u8::from_str_radix(h, 16) {
            return Some(n);
        }
    }
    None
}

impl Color {
    fn from_name(s: &str) -> Result<Color, ParseColorError> {
        match &*s.to_lowercase() {
            "black" => Ok(Color::Black),
            "blue" => Ok(Color::Blue),
            "green" => Ok(Color::Green),
            "red" => Ok(Color::Red),
            "cyan" => Ok(Color::Cyan),
            "magenta" => Ok(Color::Magenta),
            "yellow" => Ok(Color::Yellow),
            "white" => Ok(Color::White),
            _ => Err(ParseColorError {
                kind: ParseColorErrorKind::InvalidName,
                given: s.to_string(),
            }),
        }
    }

    pub fn parse(s: &str) -> Result<Color, ParseColorError> {
        let codes: Vec<&str> = s.split(',').collect();
        if codes.len() == 1 {
            if let Ok(n) = codes[0].parse::<u8>() {
                return Ok(Color::Ansi256(n));
            }
            if s.chars().all(|c| c.is_digit(16)) {
                return Err(ParseColorError {
                    kind: ParseColorErrorKind::InvalidAnsi256,
                    given: s.to_string(),
                });
            }
            if let Some(h) = s.strip_prefix("0x") {
                if let Ok(n) = u8::from_str_radix(h, 16) {
                    return Ok(Color::Ansi256(n));
                }
            }
            Color::from_name(s)
        } else if codes.len() == 3 {
            let mut v = Vec::with_capacity(3);
            for code in codes {
                match parse_u8_maybe_hex(code) {
                    Some(n) => v.push(n),
                    None => {
                        return Err(ParseColorError {
                            kind: ParseColorErrorKind::InvalidRgb,
                            given: s.to_string(),
                        })
                    }
                }
            }
            Ok(Color::Rgb(v[0], v[1], v[2]))
        } else {
            Err(ParseColorError {
                kind: if s.contains(',') {
                    ParseColorErrorKind::InvalidRgb
                } else {
                    ParseColorErrorKind::InvalidName
                },
                given: s.to_string(),
            })
        }
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ColorSpec {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
}

impl ColorSpec {
    pub fn new() -> ColorSpec {
        ColorSpec::default()
    }

    pub fn clear(&mut self) {
        *self = ColorSpec::default();
    }
}

fn write_color<W: Write>(out: &mut W, fg: bool, c: Color, intense: bool) -> io::Result<()> {
    let base = if fg { 3 } else { 4 };
    let ext = if fg { 38 } else { 48 };
    match c {
        Color::Ansi256(n) => write!(out, "\x1b[{};5;{}m", ext, n),
        Color::Rgb(r, g, b) => write!(out, "\x1b[{};2;{};{};{}m", ext, r, g, b),
        _ => {
            let code = match c {
                Color::Black => 0,
                Color::Red => 1,
                Color::Green => 2,
                Color::Yellow => 3,
                Color::Blue => 4,
                Color::Magenta => 5,
                Color::Cyan => 6,
                Color::White => 7,
                _ => unreachable!(),
            };
            if intense {
                write!(out, "\x1b[{};5;{}m", ext, code + 8)
            } else {
                write!(out, "\x1b[{}{}m", base, code)
            }
        }
    }
}

/// Emit a reset followed by the attributes of the spec.
pub fn set_color<W: Write>(out: &mut W, spec: &ColorSpec) -> io::Result<()> {
    out.write_all(b"\x1b[0m")?;
    if spec.bold {
        out.write_all(b"\x1b[1m")?;
    }
    if spec.dimmed {
        out.write_all(b"\x1b[2m")?;
    }
    if spec.italic {
        out.write_all(b"\x1b[3m")?;
    }
    if spec.underline {
        out.write_all(b"\x1b[4m")?;
    }
    if let Some(c) = spec.fg {
        write_color(out, true, c, spec.intense)?;
    }
    if let Some(c) = spec.bg {
        write_color(out, false, c, spec.intense)?;
    }
    Ok(())
}

pub fn reset<W: Write>(out: &mut W) -> io::Result<()> {
    out.write_all(b"\x1b[0m")
}
