//! Tokenization of hunk lines into words / spaces / punctuation / newline.

/// A token: byte range `[lo, hi)` within a line buffer.
#[derive(Clone, Copy, Debug)]
pub struct Token {
    pub lo: usize,
    pub hi: usize,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Word,
    Space,
    Other,
}

fn kind_of(c: char) -> Kind {
    if c.is_alphanumeric() || c == '_' {
        Kind::Word
    } else if c == ' ' || c == '\t' {
        Kind::Space
    } else {
        Kind::Other
    }
}

/// Returns true when every byte of the line is ASCII whitespace.
pub fn is_blank(line: &[u8]) -> bool {
    line.iter().all(|b| b.is_ascii_whitespace())
}

/// Length of the leading ASCII whitespace of `s`.
pub fn leading_ws(s: &[u8]) -> usize {
    s.iter().take_while(|b| b.is_ascii_whitespace()).count()
}

/// Tokenize the content of a line, which starts at byte offset `start` of
/// `line` (the part before `start` is the prefix: marker and indentation).
/// `line` includes the trailing newline if any.
pub fn tokenize(line: &[u8], start: usize, out: &mut Vec<Token>) {
    let n = line.len();
    // Determine the end-of-line token.
    let mut end = n;
    let mut eol: Option<Token> = None;
    if n > start && line[n - 1] == b'\n' {
        if n - 1 > start && line[n - 2] == b'\r' {
            end = n - 2;
        } else {
            end = n - 1;
        }
        eol = Some(Token { lo: end, hi: n });
    }
    let body = &line[start..end];
    let mut i = 0usize;
    let mut cur: Option<(usize, Kind)> = None; // (lo, kind) of an open word/space run
    let push_run = |out: &mut Vec<Token>, cur: &mut Option<(usize, Kind)>, upto: usize| {
        if let Some((lo, _)) = cur.take() {
            out.push(Token { lo: start + lo, hi: start + upto });
        }
    };
    while i < body.len() {
        match std::str::from_utf8(&body[i..]) {
            Ok(s) => {
                for (off, c) in s.char_indices() {
                    let pos = i + off;
                    let k = kind_of(c);
                    let clen = c.len_utf8();
                    match k {
                        Kind::Other => {
                            push_run(out, &mut cur, pos);
                            out.push(Token { lo: start + pos, hi: start + pos + clen });
                        }
                        _ => match cur {
                            Some((_, ck)) if ck == k => {}
                            _ => {
                                push_run(out, &mut cur, pos);
                                cur = Some((pos, k));
                            }
                        },
                    }
                }
                i = body.len();
            }
            Err(e) => {
                let valid = e.valid_up_to();
                if valid > 0 {
                    let s = std::str::from_utf8(&body[i..i + valid]).unwrap();
                    for (off, c) in s.char_indices() {
                        let pos = i + off;
                        let k = kind_of(c);
                        let clen = c.len_utf8();
                        match k {
                            Kind::Other => {
                                push_run(out, &mut cur, pos);
                                out.push(Token { lo: start + pos, hi: start + pos + clen });
                            }
                            _ => match cur {
                                Some((_, ck)) if ck == k => {}
                                _ => {
                                    push_run(out, &mut cur, pos);
                                    cur = Some((pos, k));
                                }
                            },
                        }
                    }
                }
                let pos = i + valid;
                let bad = match e.error_len() {
                    Some(l) => l,
                    None => body.len() - pos,
                };
                push_run(out, &mut cur, pos);
                out.push(Token { lo: start + pos, hi: start + pos + bad });
                i = pos + bad;
            }
        }
    }
    push_run(out, &mut cur, body.len());
    if let Some(t) = eol {
        out.push(t);
    }
}
EOF
echo ok

