//! Token-level diff: finds a (mostly) longest common subsequence between two
//! sequences, using a bidirectional variant of the greedy O(ND) algorithm with
//! divide-and-conquer.  Returns, for each token of both sides, whether it is
//! shared with the other side.

pub struct DiffResult {
    pub a_common: Vec<bool>,
    pub b_common: Vec<bool>,
}

struct Ctx<'a> {
    a: &'a [u32],
    b: &'a [u32],
    a_common: Vec<bool>,
    b_common: Vec<bool>,
    vf: Vec<isize>,
    vb: Vec<isize>,
}

enum Found {
    // forward-pass detection: forward frontier point (fx, fy)
    Fwd(usize, usize),
    // reverse-pass detection: forward frontier point on the same diagonal
    Rev(usize, usize),
}

impl<'a> Ctx<'a> {
    fn eq(&self, i: usize, j: usize) -> bool {
        self.a[i] == self.b[j]
    }

    /// Try to resolve the box directly when the common prefix and suffix
    /// together cover the shorter side.
    fn precheck(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) -> bool {
        let n = a1 - a0;
        let m = b1 - b0;
        let mn = n.min(m);
        let mut p = 0;
        while p < mn && self.eq(a0 + p, b0 + p) {
            p += 1;
        }
        let mut s = 0;
        while s < mn && self.eq(a1 - 1 - s, b1 - 1 - s) {
            s += 1;
        }
        if p + s < mn {
            return false;
        }
        if s >= p {
            for i in 0..s {
                self.a_common[a1 - 1 - i] = true;
                self.b_common[b1 - 1 - i] = true;
            }
            for i in 0..(mn - s) {
                self.a_common[a0 + i] = true;
                self.b_common[b0 + i] = true;
            }
        } else {
            for i in 0..p {
                self.a_common[a0 + i] = true;
                self.b_common[b0 + i] = true;
            }
            for i in 0..(mn - p) {
                self.a_common[a1 - 1 - i] = true;
                self.b_common[b1 - 1 - i] = true;
            }
        }
        true
    }

    fn middle(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) -> Option<Found> {
        let n = (a1 - a0) as isize;
        let m = (b1 - b0) as isize;
        let delta = n - m;
        let odd = delta % 2 != 0;
        let maxd = ((n + m) / 2 + 2) as usize;
        let size = 2 * maxd + 4;
        if self.vf.len() < size {
            self.vf.resize(size, 0);
            self.vb.resize(size, 0);
        }
        let off = maxd as isize + 1;
        for v in self.vf[..size].iter_mut() {
            *v = 0;
        }
        for v in self.vb[..size].iter_mut() {
            *v = 0;
        }
        let vf = &mut self.vf;
        let vb = &mut self.vb;
        let a = self.a;
        let b = self.b;
        for d in 0..=(maxd as isize) {
            // forward pass, ascending k
            let mut k = -d;
            while k <= d {
                let x0 = if k == -d || (k != d && vf[(k - 1 + off) as usize] < vf[(k + 1 + off) as usize]) {
                    vf[(k + 1 + off) as usize]
                } else {
                    vf[(k - 1 + off) as usize] + 1
                };
                let mut x = x0;
                let mut y = x - k;
                while x < n && y < m && y >= 0 && a[a0 + x as usize] == b[b0 + y as usize] {
                    x += 1;
                    y += 1;
                }
                vf[(k + off) as usize] = x;
                if odd {
                    let kr = delta - k;
                    if kr >= -(d - 1) && kr <= d - 1 {
                        let xr = vb[(kr + off) as usize];
                        if x + xr >= n {
                            return Some(Found::Fwd(x as usize, (x - k) as usize));
                        }
                    }
                }
                k += 2;
            }
            // reverse pass, descending k
            let mut k = d;
            while k >= -d {
                let x0 = if k == -d || (k != d && vb[(k - 1 + off) as usize] < vb[(k + 1 + off) as usize]) {
                    vb[(k + 1 + off) as usize]
                } else {
                    vb[(k - 1 + off) as usize] + 1
                };
                let mut x = x0;
                let mut y = x - k;
                while x < n && y < m && y >= 0 && a[a1 - 1 - x as usize] == b[b1 - 1 - y as usize] {
                    x += 1;
                    y += 1;
                }
                vb[(k + off) as usize] = x;
                if !odd {
                    let kf = delta - k;
                    if kf >= -d && kf <= d {
                        let xf = vf[(kf + off) as usize];
                        if x + xf >= n {
                            let fx = xf;
                            let fy = xf - kf;
                            return Some(Found::Rev(fx.max(0) as usize, fy.max(0) as usize));
                        }
                    }
                }
                k -= 2;
            }
        }
        None
    }

    fn rec(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) {
        if a0 >= a1 || b0 >= b1 {
            return;
        }
        if self.precheck(a0, a1, b0, b1) {
            return;
        }
        let n = a1 - a0;
        let m = b1 - b0;
        let (px, py) = match self.middle(a0, a1, b0, b1) {
            Some(Found::Fwd(x, y)) | Some(Found::Rev(x, y)) => (x.min(n), y.min(m)),
            None => return,
        };
        if (px == 0 && py == 0) || (px == n && py == m) {
            // degenerate split; fall back to a simple greedy alignment
            self.greedy(a0, a1, b0, b1);
            return;
        }
        self.rec(a0, a0 + px, b0, b0 + py);
        self.rec(a0 + px, a1, b0 + py, b1);
    }

    fn greedy(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) {
        let mut i = a0;
        let mut j = b0;
        while i < a1 && j < b1 {
            if self.eq(i, j) {
                self.a_common[i] = true;
                self.b_common[j] = true;
                i += 1;
                j += 1;
            } else if (a1 - i) > (b1 - j) {
                i += 1;
            } else {
                j += 1;
            }
        }
    }
}

pub fn diff(a: &[u32], b: &[u32]) -> DiffResult {
    let mut ctx = Ctx {
        a,
        b,
        a_common: vec![false; a.len()],
        b_common: vec![false; b.len()],
        vf: Vec::new(),
        vb: Vec::new(),
    };
    ctx.rec(0, a.len(), 0, b.len());
    DiffResult {
        a_common: ctx.a_common,
        b_common: ctx.b_common,
    }
}
