        --line-numbers              Display line numbers.
    -h, --help                      Prints help information
    -V, --version                   Prints version information
";

const USAGE_LONG: &str = "diffr 0.1.5
Nathan Moreau <nathan.moreau@m4x.org>

diffr adds word-level diff on top of unified diffs.
word-level diff information is displayed using text attributes.

USAGE:
    diffr reads from standard input and writes to standard output.

    Typical usage is for interactive use of diff:
    diff -u <file1> <file2> | diffr
    git show | diffr

OPTIONS:
        --colors <COLOR_SPEC>...
            Configure color settings for console ouput.

            There are four faces to customize:
            +----------------+--------------+----------------+
            |  line prefix   |      +       |       -        |
            +----------------+--------------+----------------+
            | common segment |    added     |    removed     |
            | unique segment | refine-added | refine-removed |
            +----------------+--------------+----------------+

            The customization allows
            - to change the foreground or background color;
            - to set or unset the attributes 'bold', 'intense', 'underline';
            - to clear all attributes.

            Customization is done passing a color_spec argument.
            This flag may be provided multiple times.

            The syntax is the following:

            color_spec = face-name + ':' + attributes
            attributes = attribute
                       | attribute + ':' + attributes
            attribute  = ('foreground' | 'background') + ':' + color
                       | (<empty> | 'no') + font-flag
                       | 'none'
            font-flag  = 'italic'
                       | 'bold'
                       | 'intense'
                       | 'underline'
            color      = 'none'
                       | [0-255]
                       | [0-255] + ',' + [0-255] + ',' + [0-255]
                       | ('black', 'blue', 'green', 'red',
                          'cyan', 'magenta', 'yellow', 'white')

            For example, the color_spec

                'refine-added:background:blue:bold'

            sets the color of unique added segments with
            a blue background, written with a bold font.

        --line-numbers <compact|aligned|fixed>
            Display line numbers. Style is optional.
            When style = 'compact', take as little width as possible.
            When style = 'aligned', align to tab stops (useful if tab is used for indentation). [default: compact]

    -h, --help
            Prints help information

    -V, --version
            Prints version information
";

#[derive(Clone, Copy, PartialEq, Eq)]
enum LineNumberStyle {
    Compact,
    Aligned,
    Fixed,
}

struct Config {
    added: ColorSpec,
    refine_added: ColorSpec,
    removed: ColorSpec,
    refine_removed: ColorSpec,
    whitespace: ColorSpec,
    line_numbers: Option<LineNumberStyle>,
}

fn default_config() -> Config {
    let mut added = ColorSpec::new();
    added.fg = Some(Color::Green);
    let mut refine_added = ColorSpec::new();
    refine_added.fg = Some(Color::Rgb(255, 255, 255));
    refine_added.bg = Some(Color::Green);
    refine_added.bold = true;
    let mut removed = ColorSpec::new();
    removed.fg = Some(Color::Red);
    let mut refine_removed = ColorSpec::new();
    refine_removed.fg = Some(Color::Rgb(255, 255, 255));
    refine_removed.bg = Some(Color::Red);
    refine_removed.bold = true;
    let mut whitespace = ColorSpec::new();
    whitespace.bg = Some(Color::Red);
    Config {
        added,
        refine_added,
        removed,
        refine_removed,
        whitespace,
        line_numbers: None,
    }
}

fn die(msg: &str) -> ! {
    eprintln!("{}", msg);
    process::exit(255);
}

fn parse_color_spec(config: &mut Config, spec: &str) {
    let mut parts = spec.split(':');
    let face_name = parts.next().unwrap_or("");
    let face: &mut ColorSpec = match face_name {
        "added" => &mut config.added,
        "refine-added" => &mut config.refine_added,
        "removed" => &mut config.removed,
        "refine-removed" => &mut config.refine_removed,
        other => die(&format!(
            "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed",
            other
        )),
    };
    while let Some(attr) = parts.next() {
        match attr {
            "foreground" | "background" => {
                let value = match parts.next() {
                    Some(v) => v,
                    None => die(&format!(
                        "error parsing color: missing color value for face '{}'",
                        face_name
                    )),
                };
                let color = if value == "none" {
                    None
                } else {
                    match Color::parse(value) {
                        Ok(c) => Some(c),
                        Err(e) => die(&format!("unexpected color value: {}", e)),
                    }
                };
                if attr == "foreground" {
                    face.fg = color;
                } else {
                    face.bg = color;
                }
            }
            "italic" => face.italic = true,
            "noitalic" => face.italic = false,
            "bold" => face.bold = true,
            "nobold" => face.bold = false,
            "dimmed" => face.dimmed = true,
            "nodimmed" => face.dimmed = false,
            "intense" => face.intense = true,
            "nointense" => face.intense = false,
            "underline" => face.underline = true,
            "nounderline" => face.underline = false,
            "none" => face.clear(),
            other => die(&format!(
                "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none",
                other
            )),
        }
    }
}

fn parse_args() -> Config {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.iter().any(|a| a == "--help") {
        print!("{}", USAGE_LONG);
        process::exit(0);
    }
    let mut config = default_config();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" => {
                print!("{}", USAGE_SHORT);
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("diffr {}", VERSION);
                process::exit(0);
            }
            "--colors" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("option requires an argument: '--colors'");
                    process::exit(2);
                }
                parse_color_spec(&mut config, &args[i]);
            }
            "--line-numbers" => {
                i += 1;
                if i < args.len() {
                    let style = match args[i].as_str() {
                        "compact" => LineNumberStyle::Compact,
                        "aligned" => LineNumberStyle::Aligned,
                        "fixed" => LineNumberStyle::Fixed,
                        other => die(&format!(
                            "unexpected line number style: got '{}', expected aligned|compact|fixed",
                            other
                        )),
                    };
                    config.line_numbers = Some(style);
                } else {
                    config.line_numbers = Some(LineNumberStyle::Compact);
                }
            }
            other => {
                eprintln!("bad argument: '{}'", other);
                eprint!("{}", USAGE_SHORT);
                process::exit(2);
            }
        }
        i += 1;
    }
    config
}

// ---------------------------------------------------------------------------
// Hunk handling

#[derive(Clone, Copy, PartialEq, Eq)]
enum LineKind {
    Removed,
    Added,
    Context,
    Other, // "\ No newline at end of file" and such
}

struct HunkLine {
    kind: LineKind,
    data: Vec<u8>,
    tokens: Vec<Token>, // only for Removed/Added
    blank: bool,
    prefix_len: usize, // marker + leading whitespace
}

struct Hunk {
    header: Vec<u8>,
    old_start: u64,
    old_count: u64,
    new_start: u64,
    new_count: u64,
    lines: Vec<HunkLine>,
}

fn parse_hunk_header(line: &[u8]) -> Option<(u64, u64, u64, u64)> {
    // tokens separated by ASCII whitespace
    let text = match std::str::from_utf8(line) {
        Ok(t) => t,
        Err(_) => return None,
    };
    let toks: Vec<&str> = text.split(|c: char| c.is_ascii_whitespace()).filter(|s| !s.is_empty()).collect();
    fn parse_range(s: &str) -> Option<(u64, u64)> {
        let mut it = s.split(',');
        let start = it.next()?;
        if start.is_empty() {
            return None;
        }
        let start: u64 = start.parse().ok()?;
        let count = match it.next() {
            Some(c) => {
                if c.is_empty() {
                    return None;
                }
                c.parse::<u64>().ok()?
            }
            None => 1,
        };
        if it.next().is_some() {
            return None;
        }
        Some((start, count))
    }
    for i in 0..toks.len() {
        if let Some(rest) = toks[i].strip_prefix('-') {
            let old = match parse_range(rest) {
                Some(r) => r,
                None => continue,
            };
            if i + 2 >= toks.len() {
                continue;
            }
            let new = match toks[i + 1].strip_prefix('+').and_then(parse_range) {
                Some(r) => r,
                None => continue,
            };
            if !toks[i + 2].starts_with('@') {
                continue;
            }
            return Some((old.0, old.1, new.0, new.1));
        }
    }
    None
}

fn digits(mut n: u64) -> usize {
    let mut d = 0;
    while n > 0 {
        n /= 10;
        d += 1;
    }
    d
}

struct Output<W: Write> {
    out: W,
    config: Config,
}

impl<W: Write> Output<W> {
    fn write_plain(&mut self, line: &[u8]) -> io::Result<()> {
        let (body, nl) = split_newline(line);
        color::reset(&mut self.out)?;
        self.out.write_all(body)?;
        color::reset(&mut self.out)?;
        if nl {
            self.out.write_all(b"\n")?;
        }
        Ok(())
    }

    fn write_segment(&mut self, spec: &ColorSpec, text: &[u8]) -> io::Result<()> {
        color::set_color(&mut self.out, spec)?;
        self.out.write_all(text)?;
        color::reset(&mut self.out)
    }

    fn flush_hunk(&mut self, hunk: &mut Hunk) -> io::Result<()> {
        // Tokenize and intern
        let mut intern: HashMap<&[u8], u32> = HashMap::new();
        let mut a_ids: Vec<u32> = Vec::new();
        let mut b_ids: Vec<u32> = Vec::new();
        for l in hunk.lines.iter() {
            if l.kind != LineKind::Removed {
                continue;
            }
            for t in l.tokens.iter() {
                let next = intern.len() as u32;
                let id = *intern.entry(&l.data[t.lo..t.hi]).or_insert(next);
                a_ids.push(id);
            }
        }
        for l in hunk.lines.iter() {
            if l.kind != LineKind::Added {
                continue;
            }
            for t in l.tokens.iter() {
                let next = intern.len() as u32;
                let id = *intern.entry(&l.data[t.lo..t.hi]).or_insert(next);
                b_ids.push(id);
            }
        }
        let result = diff::diff(&a_ids, &b_ids);

        // line number setup
        let ln = self.config.line_numbers;
        let width = if ln.is_some() {
            let w = digits(hunk.old_start.wrapping_add(hunk.old_count))
                .max(digits(hunk.new_start.wrapping_add(hunk.new_count)));
            if ln == Some(LineNumberStyle::Fixed) {
                w.max(3)
            } else {
                w
            }
        } else {
            0
        };
        let mut old_no = hunk.old_start;
        let mut new_no = hunk.new_start;

        let mut ai = 0usize;
        let mut bi = 0usize;
        for l in hunk.lines.iter() {
            match l.kind {
                LineKind::Other => {
                    self.write_plain(&l.data)?;
                }
                LineKind::Context => {
                    if let Some(style) = ln {
                        let field = if old_no == new_no {
                            format!("{:>w$}", old_no, w = 2 * width + 1)
                        } else {
                            format!("{:>w$} {:>w$}", old_no, new_no, w = width)
                        };
                        self.out.write_all(field.as_bytes())?;
                        if style == LineNumberStyle::Aligned {
                            self.out.write_all(b"\t")?;
                        }
                    }
                    old_no = old_no.wrapping_add(1);
                    new_no = new_no.wrapping_add(1);
                    self.write_plain(&l.data)?;
                }
                LineKind::Removed | LineKind::Added => {
                    let removed = l.kind == LineKind::Removed;
                    let (face, refine) = if removed {
                        (self.config.removed.clone(), self.config.refine_removed.clone())
                    } else {
                        (self.config.added.clone(), self.config.refine_added.clone())
                    };
                    if let Some(style) = ln {
                        let field = if removed {
                            if hunk.new_start == 0 {
                                if width == 0 {
                                    return Err(io::Error::new(io::ErrorKind::WriteZero, "failed to write whole buffer"));
                                }
                                format!("{:>w$}", old_no, w = width)
                            } else {
                                format!("{:>w$} {:w$}", old_no, "", w = width)
                            }
                        } else if hunk.old_start == 0 {
                            format!("{:>w$}", new_no, w = width)
                        } else {
                            format!("{:w$} {:>w$}", "", new_no, w = width)
                        };
                        if field.len() > 2 * width + 1 && (removed && hunk.old_start == 0 || !removed && hunk.new_start == 0) {
                            return Err(io::Error::new(io::ErrorKind::WriteZero, "failed to write whole buffer"));
                        }
                        if (removed && hunk.old_start == 0) || (!removed && hunk.new_start == 0) {
                            return Err(io::Error::new(io::ErrorKind::WriteZero, "failed to write whole buffer"));
                        }
                        self.write_segment(&face, field.as_bytes())?;
                        if style == LineNumberStyle::Aligned {
                            self.out.write_all(b"\t")?;
                        }
                    }
                    if removed {
                        old_no = old_no.wrapping_add(1);
                    } else {
                        new_no = new_no.wrapping_add(1);
                    }
                    let data = &l.data;
                    let (body, nl) = split_newline(data);
                    if l.blank {
                        self.write_segment(&face, &data[..1])?;
                        if data.len() > 1 {
                            let ws = self.config.whitespace.clone();
                            self.write_segment(&ws, &body[1..])?;
                        }
                    } else {
                        // prefix
                        self.write_segment(&face, &data[..l.prefix_len])?;
                        let common: &[bool] = if removed { &result.a_common } else { &result.b_common };
                        let idx = if removed { &mut ai } else { &mut bi };
                        let ntok = l.tokens.len();
                        let flags = &common[*idx..*idx + ntok];
                        *idx += ntok;
                        let mut pos = l.prefix_len;
                        let mut t = 0;
                        while t < ntok {
                            if flags[t] {
                                t += 1;
                                continue;
                            }
                            // unique run
                            let s = l.tokens[t].lo;
                            let mut e = l.tokens[t].hi;
                            t += 1;
                            while t < ntok && !flags[t] {
                                e = l.tokens[t].hi;
                                t += 1;
                            }
                            if s > pos {
                                self.write_segment(&face, strip_nl(&data[pos..s], data, s))?;
                            }
                            let trailing_ws = data[s..e].iter().all(|b| b.is_ascii_whitespace())
                                && e + 1 == data.len()
                                && data[e] == b'\n';
                            let spec = if trailing_ws {
                                self.config.whitespace.clone()
                            } else {
                                refine.clone()
                            };
                            self.write_segment(&spec, strip_nl(&data[s..e], data, e))?;
                            pos = e;
                        }
                        if pos < data.len() {
                            self.write_segment(&face, strip_nl(&data[pos..], data, data.len()))?;
                        }
                    }
                    if nl {
                        self.out.write_all(b"\n")?;
                    }
                }
            }
        }
        Ok(())
    }
}

/// Split off a trailing '\n' (returns body without it and whether it existed).
fn split_newline(line: &[u8]) -> (&[u8], bool) {
    if let Some((&b'\n', body)) = line.split_last() {
        (body, true)
    } else {
        (line, false)
    }
}

/// If `seg` ends at `end` == data.len() and data ends with '\n', drop it.
fn strip_nl<'a>(seg: &'a [u8], data: &[u8], end: usize) -> &'a [u8] {
    if end == data.len() && !seg.is_empty() && data[data.len() - 1] == b'\n' {
        &seg[..seg.len() - 1]
    } else {
        seg
    }
}

fn make_hunk_line(kind: LineKind, data: Vec<u8>) -> HunkLine {
    let mut tokens = Vec::new();
    let mut blank = false;
    let mut prefix_len = 1;
    if kind == LineKind::Removed || kind == LineKind::Added {
        let content = &data[1..];
        if tokenize::is_blank(content) {
            blank = true;
        } else {
            prefix_len = 1 + tokenize::leading_ws(content);
            tokenize::tokenize(&data, prefix_len, &mut tokens);
        }
    }
    HunkLine { kind, data, tokens, blank, prefix_len }
}

fn run(config: Config) -> io::Result<()> {
    let stdin = io::stdin();
    let mut input = stdin.lock();
    let stdout = io::stdout();
    let mut out = Output { out: io::BufWriter::new(stdout.lock()), config };
    let mut hunk: Option<Hunk> = None;
    let mut line: Vec<u8> = Vec::new();
    loop {
        line.clear();
        let n = input.read_until(b'\n', &mut line)?;
        if n == 0 {
            break;
        }
        let first = line[0];
        if let Some(h) = hunk.as_mut() {
            match first {
                b'-' => {
                    h.lines.push(make_hunk_line(LineKind::Removed, line.clone()));
                    continue;
                }
                b'+' => {
                    h.lines.push(make_hunk_line(LineKind::Added, line.clone()));
                    continue;
                }
                b' ' => {
                    h.lines.push(make_hunk_line(LineKind::Context, line.clone()));
                    continue;
                }
                b'\\' => {
                    h.lines.push(make_hunk_line(LineKind::Other, line.clone()));
                    continue;
                }
                _ => {
                    let mut h = hunk.take().unwrap();
                    out.flush_hunk(&mut h)?;
                }
            }
        }
        if first == b'@' {
            let (os, oc, ns, nc) = parse_hunk_header(&line).unwrap_or((0, 0, 0, 0));
            out.write_plain(&line)?;
            hunk = Some(Hunk {
                header: line.clone(),
                old_start: os,
                old_count: oc,
                new_start: ns,
                new_count: nc,
                lines: Vec::new(),
            });
        } else {
            out.write_plain(&line)?;
        }
    }
    if let Some(mut h) = hunk.take() {
        out.flush_hunk(&mut h)?;
    }
    out.out.flush()?;
    Ok(())
}

fn main() {
    let config = parse_args();
    if let Err(e) = run(config) {
        let _ = io::stdout().flush();
        eprintln!("io error: {}", e);
        process::exit(255);
    }
}
