                    else: x = Vf[k-1] + 1
                    y = x - k; x0, y0 = x, y
                    while x < N and y < M and a[a0+x] == b[b0+y]: x += 1; y += 1
                    Vf[k] = x
                    kr = delta - k
                    if odd and -(d-1) <= kr <= (d-1) and x + Vb[kr] >= N:
                        xr = Vb[kr]
                        return ('f', (x0, y0), (x, y), (N - xr, M - (xr - kr)))
                for k in rks:
