                        xf = Vf[kf]
                        return ('r', (N - x, M - y), (N - x0, M - y0), (xf, xf - kf))
            return None
        def pre(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            p = 0
            while p < N and p < M and a[a0+p] == b[b0+p]: p += 1
            s = 0
            while s < N and s < M and a[a1-1-s] == b[b1-1-s]: s += 1
            mn = min(N, M)
