            use_suffix = False
            if cover == 'sfxcover': use_suffix = (s == mn)
            elif cover == 'sfxcover2': use_suffix = (s == mn and p != mn)
            elif cover == 'pfxcover': use_suffix = not (p == mn)
            if use_suffix:
