# paper's bidirectional D&C + D<=1 base case (prefix alignment) ; optional precheck
def make(forder='asc', rorder='desc', precheck=False, d1='prefix', select='first'):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def middle(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            delta = N - M
            odd = delta % 2 != 0
            Vf = {1: 0}; Vb = {1: 0}
            maxd = N + M + 2
            for d in range(0, maxd+1):
                ks = list(range(-d, d+1, 2))
                fks = ks[::-1] if forder == 'desc' else ks
                rks = ks[::-1] if rorder == 'desc' else ks
                for k in fks:
                    if k == -d or (k != d and Vf[k-1] < Vf[k+1]): x = Vf[k+1]
                    else: x = Vf[k-1] + 1
                    y = x - k; x0, y0 = x, y
                    while x < N and y < M and a[a0+x] == b[b0+y]: x += 1; y += 1
                    Vf[k] = x
                    kr = delta - k
                    if odd and -(d-1) <= kr <= (d-1) and x + Vb[kr] >= N:
                        return ('f', d, (x0, y0), (x, y))
                for k in rks:
                    if k == -d or (k != d and Vb[k-1] < Vb[k+1]): x = Vb[k+1]
                    else: x = Vb[k-1] + 1
                    y = x - k; x0, y0 = x, y
                    while x < N and y < M and a[a1-1-x] == b[b1-1-y]: x += 1; y += 1
                    Vb[k] = x
                    kf = delta - k
                    if (not odd) and -d <= kf <= d and x + Vf[kf] >= N:
                        return ('r', d, (N - x, M - y), (N - x0, M - y0))
            return None
        def base1(a0, a1, b0, b1):
            # D <= 1: one sequence is the other with at most one insertion/deletion
            N = a1 - a0; M = b1 - b0
            p = 0
            while p < N and p < M and a[a0+p] == b[b0+p]: p += 1
            if d1 == 'prefix':
                for i in range(p): ma[a0+i] = False; mb[b0+i] = False
                if N > M:
                    for i in range(p, M): ma[a0+i+1] = False; mb[b0+i] = False
                else:
                    for i in range(p, N): ma[a0+i] = False; mb[b0+i+1] = False
            else:
                s = 0
                while s < N and s < M and a[a1-1-s] == b[b1-1-s]: s += 1
                for i in range(s): ma[a1-1-i] = False; mb[b1-1-i] = False
                mn = min(N, M)
                for i in range(mn - s): ma[a0+i] = False; mb[b0+i] = False
        def rec(a0, a1, b0, b1, depth=0):
            if a0 >= a1 or b0 >= b1: return
            if depth > 100: raise RuntimeError('depth')
            N = a1 - a0; M = b1 - b0
            if precheck:
                p = 0
                while p < N and p < M and a[a0+p] == b[b0+p]: p += 1
                if p == min(N, M):
                    for i in range(p): ma[a0+i] = False; mb[b0+i] = False
                    return
            s = middle(a0, a1, b0, b1)
            if s is None: raise RuntimeError('none')
            who, d, (x0, y0), (x1, y1) = s
            D = 2*d - 1 if who == 'f' else 2*d
            if D <= 1:
                base1(a0, a1, b0, b1); return
            for i in range(x1 - x0):
                ma[a0+x0+i] = False; mb[b0+y0+i] = False
            if (x0, y0) == (N, M) or (x1, y1) == (0, 0): raise RuntimeError('loop')
            rec(a0, a0+x0, b0, b0+y0, depth+1)
            rec(a0+x1, a1, b0+y1, b1, depth+1)
        rec(0, n, 0, m)
        return ma, mb
    return algo
