{"command":"cd /workspace && cat > src/diff.rs <<'EOF'
//! Token-level diff.
//!
//! 1. A bidirectional variant of the greedy O(ND) difference algorithm
//!    (divide and conquer around the middle snake) computes a longest
//!    common subsequence between the two token sequences.
//! 2. A post-processing pass slides the boundaries of the unique segments
//!    (when neighbouring tokens are identical) in order to reduce the number
//!    of highlighted segments.
//!
//! The result is, for each token of both sides, whether it is shared.

pub struct DiffResult {
    pub a_common: Vec<bool>,
    pub b_common: Vec<bool>,
}

struct Ctx<'a> {
    a: &'a [u32],
    b: &'a [u32],
    a_common: Vec<bool>,
    b_common: Vec<bool>,
    vf: Vec<isize>,
    vb: Vec<isize>,
}

struct Snake {
    // D value parity info: true when found in the forward pass (D odd)
    fwd: bool,
    d: isize,
    x0: usize,
    y0: usize,
    x1: usize,
    y1: usize,
}

impl<'a> Ctx<'a> {
    fn eq(&self, i: usize, j: usize) -> bool {
        self.a[i] == self.b[j]
    }

    fn mark(&mut self, i: usize, j: usize) {
        self.a_common[i] = true;
        self.b_common[j] = true;
    }

    /// Base case for an edit distance of at most one: align the common suffix
    /// first, then the remaining prefix.
    fn base_case(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) {
        let n = a1 - a0;
        let m = b1 - b0;
        let mn = n.min(m);
        let mut s = 0;
        while s < mn && self.eq(a1 - 1 - s, b1 - 1 - s) {
            s += 1;
        }
        for i in 0..s {
            self.mark(a1 - 1 - i, b1 - 1 - i);
        }
        for i in 0..(mn - s) {
            if self.eq(a0 + i, b0 + i) {
                self.mark(a0 + i, b0 + i);
            }
        }
    }

    fn middle(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) -> Option<Snake> {
        let n = (a1 - a0) as isize;
        let m = (b1 - b0) as isize;
        let delta = n - m;
        let odd = delta % 2 != 0;
        let maxd = ((n + m) / 2 + 2) as usize;
        let size = 2 * maxd + 4;
        if self.vf.len() < size {
            self.vf.resize(size, 0);
            self.vb.resize(size, 0);
        }
        let off = maxd as isize + 1;
        for v in self.vf[..size].iter_mut() {
            *v = 0;
        }
        for v in self.vb[..size].iter_mut() {
            *v = 0;
        }
        let vf = &mut self.vf;
        let vb = &mut self.vb;
        let a = self.a;
        let b = self.b;
        for d in 0..=(maxd as isize) {
            // forward pass, ascending k
            let mut k = -d;
            while k <= d {
                let x0 = if k == -d || (k != d && vf[(k - 1 + off) as usize] < vf[(k + 1 + off) as usize]) {
                    vf[(k + 1 + off) as usize]
                } else {
                    vf[(k - 1 + off) as usize] + 1
                };
                let y0 = x0 - k;
                let mut x = x0;
                let mut y = y0;
                while x < n && y < m && y >= 0 && a[a0 + x as usize] == b[b0 + y as usize] {
                    x += 1;
                    y += 1;
                }
                vf[(k + off) as usize] = x;
                if odd {
                    let kr = delta - k;
                    if kr >= -(d - 1) && kr <= d - 1 {
                        let xr = vb[(kr + off) as usize];
                        if x + xr >= n {
                            return Some(Snake {
                                fwd: true,
                                d,
                                x0: x0.max(0) as usize,
                                y0: y0.max(0) as usize,
                                x1: x as usize,
                                y1: y as usize,
                            });
                        }
                    }
                }
                k += 2;
            }
            // reverse pass, descending k
            let mut k = d;
            while k >= -d {
                let x0 = if k == -d || (k != d && vb[(k - 1 + off) as usize] < vb[(k + 1 + off) as usize]) {
                    vb[(k + 1 + off) as usize]
                } else {
                    vb[(k - 1 + off) as usize] + 1
                };
                let y0 = x0 - k;
                let mut x = x0;
                let mut y = y0;
                while x < n && y < m && y >= 0 && a[a1 - 1 - x as usize] == b[b1 - 1 - y as usize] {
                    x += 1;
                    y += 1;
                }
                vb[(k + off) as usize] = x;
                if !odd {
                    let kf = delta - k;
                    if kf >= -d && kf <= d {
                        let xf = vf[(kf + off) as usize];
                        if x + xf >= n {
                            // snake in forward coordinates: from (n-x, m-y) to (n-x0, m-y0)
                            let sx0 = (n - x).max(0) as usize;
                            let sy0 = (m - y).max(0) as usize;
                            let sx1 = (n - x0).min(n) as usize;
                            let sy1 = (m - y0).min(m) as usize;
                            return Some(Snake { fwd: false, d, x0: sx0, y0: sy0, x1: sx1, y1: sy1 });
