        self.a_common[i] = true;
        self.b_common[j] = true;
    }

    /// Base case for an edit distance of at most one: align the common suffix
    /// first, then the remaining prefix.
    fn base_case(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) {
        let n = a1 - a0;
        let m = b1 - b0;
        let mn = n.min(m);
        let mut s = 0;
        while s < mn && self.eq(a1 - 1 - s, b1 - 1 - s) {
            s += 1;
        }
        for i in 0..s {
            self.mark(a1 - 1 - i, b1 - 1 - i);
        }
        for i in 0..(mn - s) {
            if self.eq(a0 + i, b0 + i) {
                self.mark(a0 + i, b0 + i);
            }
        }
    }

    fn middle(&mut self, a0: usize, a1: usize, b0: usize, b1: usize) -> Option<Snake> {
        let n = (a1 - a0) as isize;
        let m = (b1 - b0) as isize;
