            let mut k = d;
            while k >= -d {
                let x0 = if k == -d || (k != d && vb[(k - 1 + off) as usize] < vb[(k + 1 + off) as usize]) {
                    vb[(k + 1 + off) as usize]
                } else {
                    vb[(k - 1 + off) as usize] + 1
                };
                let y0 = x0 - k;
                let mut x = x0;
                let mut y = y0;
                while x < n && y < m && y >= 0 && a[a1 - 1 - x as usize] == b[b1 - 1 - y as usize] {
                    x += 1;
                    y += 1;
