        let s = match self.middle(a0, a1, b0, b1) {
            Some(s) => s,
            None => return,
        };
        let dist = if s.fwd { 2 * s.d - 1 } else { 2 * s.d };
        if dist <= 1 {
            self.base_case(a0, a1, b0, b1);
            return;
        }
        let (x0, y0, x1, y1) = (s.x0.min(n), s.y0.min(m), s.x1.min(n), s.y1.min(m));
        let len = (x1 - x0).min(y1 - y0);
        for i in 0..len {
            if self.eq(a0 + x0 + i, b0 + y0 + i) {
                self.mark(a0 + x0 + i, b0 + y0 + i);
            }
        }
        if (x0 == n && y0 == m) || (x1 == 0 && y1 == 0) || (len == 0 && x0 == 0 && y0 == 0) || (len == 0 && x1 == n && y1 == m) {
            // degenerate; fall back to the base alignment
            self.base_case(a0, a1, b0, b1);
