# D&C with configurable tie-breaks in the greedy steps
def make(forder='asc', rorder='desc', split='snake', ftie='std', rtie='std', cover='prefix', d1='suffix'):
    def algo(a, b):
        n, m = len(a), len(b)
        ma = [True]*n; mb = [True]*m
        def down_f(V, k, d):
            if k == -d: return True
            if k == d: return False
            return V[k-1] < V[k+1] if ftie == 'std' else V[k-1] + 1 < V[k+1]
        def down_r(V, k, d):
            if k == -d: return True
            if k == d: return False
            return V[k-1] < V[k+1] if rtie == 'std' else V[k-1] + 1 < V[k+1]
        def middle(a0, a1, b0, b1):
            N = a1 - a0; M = b1 - b0
            delta = N - M
            odd = delta % 2 != 0
            Vf = {1: 0}; Vb = {1: 0}
            maxd = N + M + 2
            for d in range(0, maxd+1):
