                    y = x - k; x0, y0 = x, y
                    while x < N and y < M and a[a0+x] == b[b0+y]: x += 1; y += 1
                    Vf[k] = x
                    kr = delta - k
                    if odd and -(d-1) <= kr <= (d-1) and x + Vb[kr] >= N:
                        xr = Vb[kr]
                        return ('f', d, (x0, y0), (x, y), (N - xr, M - (xr - kr)))
                for k in rks:
                    x = Vb[k+1] if down_r(Vb, k, d) else Vb[k-1] + 1
                    y = x - k; x0, y0 = x, y
                    while x < N and y < M and a[a1-1-x] == b[b1-1-y]: x += 1; y += 1
                    Vb[k] = x
                    kf = delta - k
                    if (not odd) and -d <= kf <= d and x + Vf[kf] >= N:
                        xf = Vf[kf]
                        return ('r', d, (N - x, M - y), (N - x0, M - y0), (xf, xf - kf))
