            else:
                p = 0
                while p < mn and a[a0+p] == b[b0+p]: p += 1
                for i in range(p): ma[a0+i] = False; mb[b0+i] = False
                for i in range(mn - p):
                    if a[a1-1-i] == b[b1-1-i]: ma[a1-1-i] = False; mb[b1-1-i] = False
        def rec(a0, a1, b0, b1, depth=0):
            if a0 >= a1 or b0 >= b1: return
            if depth > 200: raise RuntimeError('depth')
            N = a1 - a0; M = b1 - b0; mn = min(N, M)
            p = 0
            while p < mn and a[a0+p] == b[b0+p]: p += 1
            if p == mn:
