//! Token-level diff.
//!
//! 1. The greedy O(ND) difference algorithm computes a longest common
//!    subsequence between the two token sequences, keeping the full trace so
//!    that the alignment can be recovered.  Hunks that would need more than
//!    `MAX_DISTANCE` edits are not refined at all (everything is reported as
//!    unique), which bounds both time and memory.
//! 2. A post-processing pass slides the boundaries of the unique segments
//!    (when neighbouring tokens are identical) in order to reduce the number
//!    of highlighted segments.
//!
//! The result is, for each token of both sides, whether it is shared.

pub struct DiffResult {
    pub a_common: Vec<bool>,
    pub b_common: Vec<bool>,
}

/// Largest edit distance for which the word-level refinement is computed.
const MAX_DISTANCE: isize = 1998;

/// Greedy forward O(ND) search with a full trace.  Returns false when the
/// edit distance exceeds `MAX_DISTANCE`.
///
/// When the two candidate predecessors of a diagonal reach the same column,
/// the horizontal move (a deletion) is preferred.
fn forward_myers(a: &[u32], b: &[u32], a_common: &mut [bool], b_common: &mut [bool]) -> bool {
    let n = a.len() as isize;
    let m = b.len() as isize;
    let maxd = ((n + m) as isize).min(MAX_DISTANCE);
    let off = maxd + 1;
    let mut v: Vec<isize> = vec![0; (2 * maxd + 3) as usize];
    // trace[d] holds, for k in -d-1..=d+1 step 2, the value of v[k] before
    // iteration d (index (k + d + 1) / 2).
    let mut trace: Vec<Vec<i32>> = Vec::with_capacity(maxd as usize + 1);
    let mut found = false;
    for d in 0..=maxd {
        let mut snapshot: Vec<i32> = Vec::with_capacity(d as usize + 2);
        let mut kk = -d - 1;
        while kk <= d + 1 {
            snapshot.push(v[(kk + off) as usize] as i32);
            kk += 2;
        }
        trace.push(snapshot);
        let mut k = -d;
        while k <= d {
            let vm = v[(k - 1 + off) as usize];
            let vp = v[(k + 1 + off) as usize];
            let down = k == -d || (k != d && vm + 1 < vp);
            let mut x = if down { vp } else { vm + 1 };
            let mut y = x - k;
            while x < n && y < m && y >= 0 && a[x as usize] == b[y as usize] {
                x += 1;
                y += 1;
            }
            v[(k + off) as usize] = x;
            if x >= n && y >= m {
                found = true;
                break;
            }
            k += 2;
        }
        if found {
            break;
        }
    }
    if !found {
        return false;
    }
    // backtrack
    let mut x = n;
    let mut y = m;
    let mut d = trace.len() as isize - 1;
    while d >= 0 {
        let snap = &trace[d as usize];
        let k = x - y;
        let get = |kk: isize| -> isize {
            let idx = (kk + d + 1) / 2;
            if idx < 0 || idx as usize >= snap.len() {
                0
            } else {
                snap[idx as usize] as isize
            }
        };
        let vm = get(k - 1);
        let vp = get(k + 1);
        let down = k == -d || (k != d && vm + 1 < vp);
        let prev_k = if down { k + 1 } else { k - 1 };
        let prev_x = if down { vp } else { vm };
        let prev_y = prev_x - prev_k;
        let (sx, sy) = if d == 0 {
            (0, 0)
        } else if down {
            (prev_x, prev_y + 1)
        } else {
            (prev_x + 1, prev_y)
        };
        while x > sx && y > sy {
            x -= 1;
            y -= 1;
            a_common[x as usize] = true;
            b_common[y as usize] = true;
        }
        if d > 0 {
            x = prev_x;
            y = prev_y;
        }
        d -= 1;
    }
    true
}

/// Slide unique/common segments of one side to reduce the number of segments.
fn optimize_side(tokens: &[u32], common: &mut [bool]) {
    let n = tokens.len();
    let mut passes = 0;
    loop {
        passes += 1;
        if passes > 1000 {
            break;
        }
        let mut changed = false;
        let mut i = 0;
        while i < n {
            let mut j = i;
            while j < n && common[j] == common[i] {
                j += 1;
            }
            let uniq = !common[i];
            if uniq {
                // unique run [i, j): it may move while the token leaving it
                // equals the token entering it.
                let mut left = 0;
                while i >= left + 1 && common[i - left - 1] && tokens[i - left - 1] == tokens[j - left - 1] {
                    left += 1;
                }
                let mut right = 0;
                while j + right < n && common[j + right] && tokens[j + right] == tokens[i + right] {
                    right += 1;
                }
                if left > 0 || right > 0 {
                    let score = |sh: isize| -> i32 {
                        let ni = (i as isize + sh) as usize;
                        let nj = (j as isize + sh) as usize;
                        let in_run = |p: usize| p >= i && p < j;
                        let merge_left = ni > 0 && !common[ni - 1] && !in_run(ni - 1);
                        let merge_right = nj < n && !common[nj] && !in_run(nj);
                        let start = ni == 0;
                        let end = nj == n;
                        4 * merge_left as i32 + 4 * merge_right as i32 + 2 * start as i32 + end as i32
                    };
                    let mut best: Option<(i32, isize)> = None;
                    let mut sh = -(left as isize);
                    while sh <= right as isize {
                        let sc = score(sh);
                        match best {
                            Some((bs, bsh)) if sc < bs || (sc == bs && sh <= bsh) => {}
                            _ => best = Some((sc, sh)),
                        }
                        sh += 1;
                    }
                    let (_, sh) = best.unwrap();
                    if sh != 0 {
                        for t in i..j {
                            common[t] = true;
                        }
                        let ni = (i as isize + sh) as usize;
                        let nj = (j as isize + sh) as usize;
                        for t in ni..nj {
                            common[t] = false;
                        }
                        changed = true;
                        break;
                    }
                }
            } else if !(i == 0 && j == n) {
                // a common run made of identical tokens may slide to merge
                // with another common run
                let tok = tokens[i];
                if tokens[i..j].iter().all(|&t| t == tok) {
                    let mut left = 0;
                    while i >= left + 1 && !common[i - left - 1] && tokens[i - left - 1] == tok {
                        left += 1;
                    }
                    let mut right = 0;
                    while j + right < n && !common[j + right] && tokens[j + right] == tok {
                        right += 1;
                    }
                    if left > 0 || right > 0 {
                        let score = |sh: isize| -> i32 {
                            let ni = (i as isize + sh) as usize;
                            let nj = (j as isize + sh) as usize;
                            let in_run = |p: usize| p >= i && p < j;
                            let merge_left = ni > 0 && common[ni - 1] && !in_run(ni - 1);
                            let merge_right = nj < n && common[nj] && !in_run(nj);
                            merge_left as i32 + merge_right as i32
                        };
                        let mut best: (i32, isize) = (0, 0);
                        let mut sh = -(left as isize);
                        while sh <= right as isize {
                            let sc = score(sh);
                            if sc > best.0 || (sc == best.0 && sc > 0 && sh > best.1) {
                                best = (sc, sh);
                            }
                            sh += 1;
                        }
                        if best.0 > 0 && best.1 != 0 {
                            for t in i..j {
                                common[t] = false;
                            }
                            let ni = (i as isize + best.1) as usize;
                            let nj = (j as isize + best.1) as usize;
                            for t in ni..nj {
                                common[t] = true;
                            }
                            changed = true;
                            break;
                        }
                    }
                }
            }
            i = j;
        }
        if !changed {
            break;
        }
    }
}

pub fn diff(a: &[u32], b: &[u32]) -> DiffResult {
    let mut a_common = vec![false; a.len()];
    let mut b_common = vec![false; b.len()];
    if a.is_empty() || b.is_empty() {
        return DiffResult { a_common, b_common };
    }
    if !forward_myers(a, b, &mut a_common, &mut b_common) {
        // too many differences: no refinement
        return DiffResult {
            a_common: vec![false; a.len()],
            b_common: vec![false; b.len()],
        };
    }
    optimize_side(a, &mut a_common);
    optimize_side(b, &mut b_common);
    DiffResult { a_common, b_common }
}
